'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { LRUCache } = require('./src/lru');

test('rejects every invalid capacity category', () => {
  for (const capacity of [undefined, null, 0, -0, -1, 0.5, 1.5, Infinity, -Infinity, NaN, '2', true, false, {}, [], new Number(2), 2n, Symbol('capacity')]) {
    assert.throws(() => new LRUCache(capacity), RangeError);
  }
  assert.throws(() => new LRUCache(), RangeError);
  for (const capacity of [1, 2, Number.MAX_SAFE_INTEGER, Number.MAX_VALUE]) {
    const cache = new LRUCache(capacity);
    cache.set('key', 'value');
    assert.equal(cache.get('key'), 'value');
  }
});

test('stored undefined refreshes recency; has and misses do not', () => {
  const cache = new LRUCache(2);
  cache.set('a', undefined).set('b', 2);
  assert.equal(cache.get('a'), undefined);
  assert.equal(cache.has('b'), true);
  assert.equal(cache.get('missing'), undefined);
  cache.set('c', 3);
  assert.equal(cache.has('a'), true);
  assert.equal(cache.has('b'), false);
  assert.equal(cache.has('missing'), false);
  assert.equal(cache.size, 2);
});

test('updates preserve size and refresh recency, including capacity one', () => {
  const cache = new LRUCache(2);
  cache.set('a', 1).set('b', 2);
  assert.equal(cache.set('a', 9), cache);
  assert.equal(cache.size, 2);
  assert.equal(cache.has('b'), true);
  cache.set('c', 3);
  assert.equal(cache.has('b'), false);
  assert.equal(cache.get('a'), 9);
  const single = new LRUCache(1);
  single.set(undefined, 1).set(undefined, 2);
  assert.equal(single.size, 1);
  assert.equal(single.get(undefined), 2);
  single.set('other', 3);
  assert.equal(single.has(undefined), false);
  assert.equal(single.get('other'), 3);
});

test('keys and values obey Map identity and SameValueZero semantics', () => {
  const object = {};
  const otherObject = {};
  const symbol = Symbol('key');
  const otherSymbol = Symbol('key');
  const fn = () => {};
  const pairs = [[object, otherObject], [otherObject, object], [symbol, fn], [otherSymbol, null], [fn, symbol], [NaN, NaN], [-0, false], [undefined, undefined], [null, 0], ['1', 1n], [1, 'one'], [1n, true], [false, Infinity]];
  const cache = new LRUCache(pairs.length);
  for (const [key, value] of pairs) cache.set(key, value);
  for (const [key, value] of pairs) assert.equal(cache.get(key), value);
  assert.equal(cache.has({}), false);
  assert.equal(cache.has(Symbol('key')), false);
  assert.equal(cache.get(0), false);
  cache.set(0, 'zero');
  cache.set(Number('not a number'), 'nan');
  assert.equal(cache.size, pairs.length);
  assert.equal(cache.get(-0), 'zero');
  assert.equal(cache.get(NaN), 'nan');
});

test('deletion preserves surviving recency and reinsertion is most recent', () => {
  const cache = new LRUCache(3);
  cache.set('a', 1).set('b', undefined).set('c', 3);
  assert.equal(cache.delete('b'), true);
  assert.equal(cache.delete('b'), false);
  assert.equal(cache.size, 2);
  cache.set('b', 4).set('d', 5);
  assert.equal(cache.has('a'), false);
  assert.equal(cache.has('c'), true);
  cache.set('e', 6);
  assert.equal(cache.has('c'), false);
  assert.equal(cache.get('b'), 4);
});

test('cache instances keep independent storage and recency', () => {
  const first = new LRUCache(1);
  const second = new LRUCache(2);
  first.set('a', 1);
  second.set('a', 2).set('b', 3);
  first.set('c', 4);
  assert.equal(first.has('a'), false);
  assert.equal(second.get('a'), 2);
  assert.equal(second.delete('b'), true);
  assert.equal(first.get('c'), 4);
  assert.equal(first.size, 1);
  assert.equal(second.size, 1);
});

